"""Terminal output helpers: step headers, colored status lines, fields."""

from __future__ import annotations

import os
import platform
import sys

_COLOR_ENABLED = sys.stdout.isatty() and "NO_COLOR" not in os.environ


def stop_hint() -> str:
    return "Ctrl+C" if platform.system() == "Windows" else "Control-C"


def _code(value: str) -> str:
    return f"\033[{value}m" if _COLOR_ENABLED else ""


RESET = _code("0")
BOLD = _code("1")
DIM = _code("2")
_CYAN = _code("36")
_GREEN = _code("32")
_YELLOW = _code("33")
_RED = _code("31")
_BLUE = _code("34")


def banner(text: str) -> None:
    """Top-level title."""
    print(f"{BOLD}{text}{RESET}")


def step(number: int, total: int, title: str) -> None:
    """Header for one step, e.g. 'Step 2/3  Stream & record your data'."""
    print()
    print(f"{BOLD}{_CYAN}Step {number}/{total}{RESET}  {BOLD}{title}{RESET}")


def info(message: str) -> None:
    print(message)


def detail(message: str) -> None:
    """Secondary/dim line (hints, context)."""
    print(f"{DIM}{message}{RESET}")


def field(label: str, value: str) -> None:
    """A labeled value, e.g. a verification code."""
    print(f"{DIM}{label}:{RESET} {BOLD}{value}{RESET}")


def link(url: str) -> None:
    print(f"{_BLUE}{BOLD}{url}{RESET}")


def success(message: str) -> None:
    print(f"{_GREEN}✓ {message}{RESET}")


def warn(message: str) -> None:
    print(f"{_YELLOW}! {message}{RESET}")


def error(message: str) -> None:
    print(f"{_RED}✗ {message}{RESET}")
